    if k == 1:
        count_ones = cards.count('1')
        return "once again" if count_ones % 2 != 0 else "tokitsukaze"

    # Check if there's a winning strategy for Tokitsukaze
    def can_win(cards, k):
        for i in range(n - k + 1):
            if sum(1 for j in range(k) if cards[i+j] == '1') % 2 != 0:
                flipped_cards = list(cards)
                for j in range(k):
                    flipped_cards[i+j] = '0' if flipped_cards[i+j] == '1' else '1'
                if all(card == flipped_cards[0] for card in flipped_cards):
                    return True
        return False

    if can_win(cards, k):
        return "tokitsukaze"
    else:
        return "quailty"

