def determine_winner(n, k, cards):
    def count_flips(cards):
        flips = 0
        current_color = cards[0]
        for card in cards:
            if card != current_color:
                flips += 1
                current_color = card
        return flips // k + bool(flips % k)

    tokitsukaze_flips = count_flips(cards)
    quailty_flips = count_flips(cards[::-1])

    if tokitsukaze_flips > 10**9 or quailty_flips > 10**9:
        return "once again"
    elif tokitsukaze_flips < quailty_flips:
        return "tokitsukaze"
    else:
        return "quailty"

